bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
echo VIDEO_RUNTIME_RUNNING=PASS
docker exec "$cid" sh -c 'grep -n "VIDEO_TOPIC_NOT_CONNECTED\|VIDEO_REVIEW_NOT_CONNECTED\|getVerifiedVideoTopic\|verifyReview" /opt/videobot/owner/gateOwner.mjs | head -n 18'
docker exec "$cid" sh -c 'grep -n "VIDEO_PUBLICATION_PRE_SEND_REJECTED\|PUBLISH_NEEDS_RECONCILE\|markPublished" /opt/videobot/src/telegram/creatorWizard.mjs | head -n 16'
docker exec "$cid" sh -c 'grep -n "getVerifiedVideoTopic\|verifyReview\|sendPaidMedia" /opt/videobot/src/telegram/paidListingPublisher.mjs | head -n 20'
docker exec "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
const c=new pg.Client({connectionString:process.env.DATABASE_URL});
try {
 await c.connect();
 const tables=await c.query("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name LIKE 'videobot_%' AND (table_name LIKE '%listing%' OR table_name LIKE '%receipt%' OR table_name LIKE '%session%') ORDER BY table_name");
 console.log("VIDEO_TABLES="+tables.rows.map(x=>x.table_name).join(","));
 for(const row of tables.rows) {
  const cols=await c.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position",[row.table_name]);
  console.log("VIDEO_COLUMNS_"+row.table_name+"="+cols.rows.map(x=>x.column_name).join(","));
 }
} catch(e){console.log("VIDEO_DB_DIAGNOSTIC="+e.code);process.exitCode=78}
finally {await c.end().catch(()=>{})}
NODE
echo VIDEO_READONLY_DIAGNOSTIC=COMPLETE
